mb:micro.mb:pseudocode:
resolveVisibility(setting, coarseMatches):
    if (setting === "show") return "visible";
    if (setting === "hide") return "collapsed";
    return coarseMatches ? "visible" : "collapsed";
// the handle is rendered in both states; only the bar body collapses
render: <button class="expand-handle" aria-expanded={visible}> always present, 48x48

render: for d in 1..9 -> <button type="button" data-digit={d} aria-pressed="false">
onDigitTap(d): activeDigit = (activeDigit === d) ? null : d;
               update aria-pressed on all nine; notify board highlight
// type="button" matters: inside a form a bare <button> submits

onCellTap(index):
    if (givens[index]) { announcer.announce("given-rejected", "고정된 칸입니다"); return; }
    if (activeDigit === null) { boardView.select(index); return; }      // Cell First
    return sticky ? store.toggleCandidate(index, activeDigit)
                  : store.setValue(index, activeDigit,
                                   {autoRemoveCandidates: settings.autoRemoveCandidates});

onPencilTap():
    sticky = !sticky;
    pencilBtn.setAttribute("aria-pressed", String(sticky));
    boardRoot.dataset.candidateMode = sticky ? "1" : "0";   // dashed outline via CSS
    badge.hidden = !sticky;                                  // text badge, not colour
    announcer.announce("sticky-mode", sticky ? "후보 입력 모드 켜짐" : "후보 입력 모드 꺼짐");

onPointerDown(index): timer = setTimeout(() => { fired = true;
    navigator.vibrate?.(10); cb.openNoteEditor({kind:"cell", key:index}); }, 400);
onPointerMove(e): if (moved beyond slop) clearTimeout(timer);   // it was a scroll
onPointerUp(): clearTimeout(timer); if (!fired) onCellTap(index); fired = false;
onMemoTap(): selection === null ? cb.openNotesList() : cb.openNoteEditor(currentTarget);

mb:micro.mb:input-type:
mountNotes(root, store, deps: {
  confirm: (question: string) => Promise<boolean>,      // DV-06: 함수 계약만 의존
  announcer: Announcer
}) -> NotesView
NotesView.openEditor(target: NoteTarget, originEl: Element | null) -> void

mb:micro.mb:pseudocode:
openEditor(target, originEl):
    draft = store.getNote(target);
    render editor outside the board rect; textarea.value = draft;
    textarea.focus();                    // initial focus only
    // deliberately NOT doing: aria-modal, inert background, tab cycling
close(): originEl?.focus();

async function cancel() {
    if (dirty && !(await deps.confirm("작성 중인 메모를 버릴까요?"))) return;
    close();
}
function save() { store.setNote(target, textarea.value); announce("note", ...); close(); }
// no blur handler, no visibilitychange handler: dismissing the keyboard is not an intent

.cell[data-note="1"]::after { content: ""; pointer-events: none; /* 7px triangle */ }
/* a pseudo-element cannot be focused or tapped, which enforces V4-05 structurally
   rather than by remembering to set an attribute */

openTargetSelector(selection):
    for kind of ["cell","row","column","box"]:
        <button> targetLabel(targetFromSelection(selection, kind)) </button>
    on pick -> openEditor(target, originEl)
openNotesList(): list every stored note with targetLabel and a preview;
                 hovering or focusing a row highlights affectedCells(target)

open(spec):
    if (current) throw new Error("DialogHost does not support nested dialogs");
    previous = document.activeElement;
    backgroundEls.forEach(el => el.inert = true);
    render role="dialog" aria-modal="true" aria-labelledby=title
    focus the first action or the body's first focusable
    trap Tab within the dialog; Escape resolves "cancel"
close(result):
    backgroundEls.forEach(el => el.inert = false);
    previous?.focus(); current = null; resolve(result);
confirm(q) = open({kind:"confirm", ...}).then(r => r === "ok");

confirm(question):
    return open({kind:"confirm", title:"확인", body:text(question),
                 actions:[{id:"cancel", label:"취소", initialFocus:true},
                          {id:"ok",     label:"계속", destructive:true}]})
           .then(r => r === "ok");
// initial focus on cancel: an accidental Enter must not destroy work

async function buildLink(scope) {
    const link = location.origin + location.pathname + "#s=" + await encode(session, scope, savedAt);
    if (scope === "SC3" && link.length > 8000)
        return {ok:false, code:"too-long", suggest:"SC2"};
    return {ok:true, link, warn: link.length > 2000};
}
// never assigns location.hash and never calls pushState (V4-12 address policy)

async function copy(link) {
    try { await navigator.clipboard.writeText(link);
          announcer.announce("link-copied", "링크를 복사했습니다"); }
    catch { showSelectableInput(link);          // readonly input, pre-selected
            announcer.announce("link-copied", "복사 권한이 없어 직접 선택할 수 있게 표시했습니다"); }
}
function share(link) {                           // called directly from the click handler
    if (navigator.share) navigator.share({url: link}).catch(() => {});
}
